  'WT 387': { role: '시스템 콤퍼넌트 B', type: 'binder', face: '#ffffff', flop: '#ffffff', desc: '수용성 베이스코트 도료 전체의 시스템 점도 조절제 및 바인더입니다.', details: [['일반 특성', '안정적인 분산과 흐름성을 관리하는 시스템 점도 조절제 및 바인더입니다.'], ['색상 및 외관 변화', '건조 시 완벽한 투명 상태가 되며 도막에 균일하고 매끄러운 펴짐성을 부여합니다.'], ['용도 및 적용 컬러', '모든 수성 컬러 시스템에 사용됩니다.'], ['배합 및 혼합 비율', '요구 중량을 한 치의 오차 없이 정밀 투입해야 합니다.'], ['경고 및 주의사항', '비율이 초과하면 흘러내림이 발생하므로 계량에 집중해야 합니다.']] },
  'WT 388': { role: '슈퍼 딥 블랙', type: 'solid', face: '#050505', flop: '#000000', desc: '빛 반사를 억제하여 깊이감을 극대화한 아주 어두운 고농축 흑색 조색제입니다.', details: [['일반 특성', '빛 반사를 억제하여 깊이감을 극대화한 아주 어두운 고농축 흑색 조색제입니다.'], ['색상 및 외관 변화', '탁한 회색 기운이 없이 맑으면서도 훨씬 더 어둡고 묵직한 진흑색 솔리드 표면을 만들어냅니다.'], ['용도 및 적용 컬러', '고급 승용차의 완전한 딥 블랙 솔리드 컬러나 특수 다크 펄 이펙트 조색 시 한정적으로 적용됩니다.'], ['배합 및 혼합 비율', '대체 사용 시 감량하여 테스트 후 투입합니다.'], ['경고 및 주의사항', '밝은 메탈릭에 한 방울이라도 섞이면 즉시 탁색으로 망치게 되니 사용을 주의하십시오.']] },
  'WT 389': { role: '플래티닌 실버 화인', type: 'silver_fine', face: '#cbd5e1', flop: '#64748b', desc: '입자 크기가 정밀하게 통제된 작은 사이즈의 고휘도 광휘형 알루미늄 조색제입니다.', details: [['일반 특성', '입자 크기가 정밀하게 통제된 작은 사이즈의 고휘도 광휘형 알루미늄 수성 조색제입니다.'], ['색상 및 외관 변화', '거칠지 않고 세밀한 금속 반사광과 뛰어난 정면 명도를 동시에 제공합니다.'], ['용도 및 적용 컬러', '특정 아시안 OEM 차량의 중간 입자 실버 매칭에 타겟팅됩니다.'], ['배합 및 혼합 비율', '지정 수량을 준수하여 계측, 배합합니다.'], ['경고 및 주의사항', '입자 배열에 따라 색상이 민감하게 변하므로 숨김 도장 영역을 충분히 넓게 확보하고 저압으로 플래시오프 해야 이색을 잡을 수 있습니다.']] },
