  'WT 392': { role: '매직 이펙트', type: 'pearl', face: '#22c55e', flop: '#ef4444', desc: '다층 박막 코팅 기술을 적용한 특수 광학 간섭 펄 조색제입니다.', details: [['일반 특성', '관찰 각도에 따라 색상이 마법처럼 카멜레온 변이를 일으키는 특수 광학 간섭 펄 조색제입니다.'], ['색상 및 외관 변화', '정면은 맑은 녹색, 측면 45도는 맑은 적색, 110도 끝에서는 약하게 적색으로 변환됩니다.'], ['용도 및 적용 컬러', '특수한 다색 교차 이펙트를 지닌 OEM 컬러 조색용으로 한정 사용됩니다.'], ['배합 및 혼합 비율', '하이테크 안료이므로 특수 배합표 지침에 따라 0.1g 단위의 오차 없이 저울링합니다.'], ['경고 및 주의사항', '바탕색(프라이머) 명도가 매뉴얼 규정과 완벽히 일치해야 색상 변이가 제대로 일어납니다.']] },
  'WT 393': { role: '라이트 옐로우', type: 'solid', face: '#fef08a', flop: '#a16207', desc: '차가운 녹색 기운을 아주 미세하게 띠면서 레몬처럼 밝고 산뜻한 연황색 조색제입니다.', details: [['일반 특성', '레몬처럼 밝고 산뜻한 톤을 가진 연황색 조색제입니다.'], ['색상 및 외관 변화', '탁함이나 붉은 기운이 배제된 깨끗한 밝은 옐로우 광선을 형성하며 바탕을 가볍게 밝혀줍니다.'], ['용도 및 적용 컬러', '주로 파스텔톤 솔리드 황색 베이스로 듬직하게 사용됩니다.'], ['배합 및 혼합 비율', '기존 WT327 황색 안료 대비 투입량을 조절하여 명도를 맞춥니다.'], ['경고 및 주의사항', '이펙트 실버 배합에 임의로 첨가 시 알루미늄 광택을 페인트로 덮어버린 듯 탁하게 만들 수 있으니 주의 바랍니다.']] },
  'WT 1051': { role: '블랜딩 1051', type: 'binder', face: '#ffffff', flop: '#ffffff', desc: '부분 보수 도장 작업 시 필수적인 전용 블랜딩(숨김) 첨가제입니다.', details: [['일반 특성', '수성 페인트 부분 보수 도장의 경계면을 자연스럽게 무너뜨리고 녹여주는 필수적인 전용 블랜딩 수지 첨가제입니다.'], ['색상 및 외관 변화', '새로 도장한 부위와 기존 도장면 사이의 오버스프레이 먼지를 부드럽게 녹여 이색 경계를 완벽히 지워줍니다.'], ['용도 및 적용 컬러', '은색 등 이색이 나기 쉬운 까다로운 메탈릭 차량의 부분 도장 작업 시 필수적으로 전처리 용도로 사용합니다.'], ['배합 및 혼합 비율', '마지막 도료를 컵에 남긴 상태에서 본품을 다량 희석하여 경계선에 흩뿌리며 사용합니다.'], ['경고 및 주의사항', '과도하게 두껍게 뿌리면 페인트 입자가 흘러내리거나 테두리에 링마크가 뜰 수 있으므로 얇고 부드럽게 미스트 형태로 분사해야 합니다.']] },
  'WT 1500': { role: '울트라 딥 블랙', type: 'solid', face: '#000000', flop: '#000000', desc: '명도가 가장 극도로 어둡게 떨어지는 한정판 흑색 조색제입니다.', details: [['일반 특성', '명도가 가장 극도로 어둡게 떨어지는 한정판 흑색 조색제입니다. 특수 염료를 함유하고 있습니다.'], ['색상 및 외관 변화', '빛을 완전히 흡수하여 극한의 검은 심연 같은 질감을 연출합니다.'], ['용도 및 적용 컬러', '일반 블랙 안료로는 도저히 맞출 수 없는 프리미엄 브랜드의 극한 다크 컬러 배합에만 독점적으로 쓰입니다.'], ['배합 및 혼합 비율', '엄격한 배합 한계치(솔리드 5%, 실버 2%, 펄 5%)를 절대적으로 준수해야 합니다.'], ['경고 및 주의사항', '허용 배합 비율 초과 시 염료가 이펙트 입자와 비정상 반응하여 색상이 치명적으로 변질될 수 있으므로 절대 주의하십시오.']] },
  'WT 455': { role: '퍼포먼스 컴포넌트', type: 'binder', face: '#ffffff', flop: '#ffffff', desc: '물성을 극적으로 안정화시키는 솔리드 전용 고성능 기능성 유동성 첨가제입니다.', details: [['일반 특성', '솔리드 전용 고성능 기능성 유동성 첨가제입니다.'], ['색상 및 외관 변화', '도막의 펴짐성을 극한으로 끌어올려 유리면처럼 매끄러운 고품질 외관을 보장합니다.'], ['용도 및 적용 컬러', '이펙트 입자가 없는 솔리드 컬러 도장 작업에만 단독으로 사용됩니다.'], ['배합 및 혼합 비율', '솔리드 베이스코트 도료 총 무게를 기준으로 정확히 10% 중량을 추가 계량하여 혼합 및 분사합니다.'], ['경고 및 주의사항', '성분 특성 상 이펙트 컬러에는 절대 사용을 금지합니다.']] },
  'WT 3080': { role: '스페셜 애디티브', type: 'binder', face: '#ffffff', flop: '#ffffff', desc: '도막 보정 및 흐름 방지 특수 첨가제.', details: [['일반 특성', '도막 보정 및 흐름 방지 전용 특수 첨가제입니다.']] }
